const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=n=>({dash:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>',plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M12 5v14M5 12h14"/></svg>',list:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>',report:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 19V9M10 19V5M16 19v-7M22 19V2"/></svg>',settings:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a2 2 0 0 0 .4 2.2l.1.1-2.6 2.6-.1-.1a2 2 0 0 0-2.2-.4 2 2 0 0 0-1.2 1.8V21h-3.6v-.2A2 2 0 0 0 9 19a2 2 0 0 0-2.2.4l-.1.1-2.6-2.6.1-.1A2 2 0 0 0 4.6 15a2 2 0 0 0-1.8-1.2H3v-3.6h.2A2 2 0 0 0 5 9a2 2 0 0 0-.4-2.2l-.1-.1 2.6-2.6.1.1A2 2 0 0 0 9 4.6a2 2 0 0 0 1.2-1.8V3h3.6v.2A2 2 0 0 0 15 5a2 2 0 0 0 2.2-.4l.1-.1 2.6 2.6-.1.1A2 2 0 0 0 19.4 9a2 2 0 0 0 1.8 1.2h.2v3.6h-.2A2 2 0 0 0 19.4 15z"/></svg>',user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>'})[n];
const seed=[{id:'DS-261012-1042',number:'9876543210',name:'Aarav Mehta',email:'aarav@email.com',location:'Goa',query:'Family holiday package',remark:'4 nights, beach property',status:'New',created:'2026-10-12',owner:'User'},{id:'DS-261011-7831',number:'9988776655',name:'Neha Shah',email:'neha@email.com',location:'Manali',query:'Honeymoon booking',remark:'December first week',status:'In Progress',created:'2026-10-11',owner:'User'},{id:'DS-261009-4610',number:'9123456780',name:'Rohan Das',email:'rohan@email.com',location:'Jaipur',query:'Corporate group tour',remark:'18 persons',status:'Closed',created:'2026-10-09',owner:'Support'}];
let state=JSON.parse(localStorage.getItem('dhruvSetuState')||'null')||{dockets:seed,fields:[{id:1,label:'Preferred Hotel Category',type:'Dropdown',options:'3 Star, 4 Star, 5 Star',enabled:true},{id:2,label:'Need Airport Pickup?',type:'Checkbox',options:'',enabled:true}],reportsAllowed:true,mail:{host:'smtp.gmail.com',port:'587',sender:'bookings@dhruvsetu.in',subject:'Your booking request {{docket_number}}',body:'Hello {{customer_name}},\n\nYour docket {{docket_number}} has been created for {{location}}. Our travel team will contact you shortly.\n\nThank you,\nDhruv-Setu Team'}};
let session=JSON.parse(sessionStorage.getItem('dsSession')||'null'),page='dashboard';
const save=()=>localStorage.setItem('dhruvSetuState',JSON.stringify(state));
const toast=m=>{const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
const users={user:{pass:'user123',name:'Amit Kumar',email:'user@dhruvsetu.in'},support:{pass:'support123',name:'Priya Support',email:'support@dhruvsetu.in'},admin:{pass:'admin123',name:'Balram Admin',email:'admin@dhruvsetu.in'}};
function loginView(){return `<section class="login-shell"><div class="brand-panel"><div class="logo"><span class="logo-mark">⌁</span>Dhruv-Setu</div><div class="brand-copy"><span class="eyebrow">Tourism CRM</span><h1>Every journey,<br><em>beautifully managed.</em></h1><p>From first enquiry to final booking—bring your customers, travel dockets and team together in one seamless workspace.</p></div><div class="mini-stats"><div><strong>One place</strong><span>All customer dockets</span></div><div><strong>3 roles</strong><span>Built for your team</span></div><div><strong>24 × 7</strong><span>Always accessible</span></div></div></div><div class="login-side"><form class="login-card" id="loginForm"><div class="logo" style="color:var(--dark);margin-bottom:45px"><span class="logo-mark">⌁</span>Dhruv-Setu</div><h2>Welcome back</h2><p class="sub">Sign in to continue to your CRM workspace.</p><div class="field"><label>Email address or User ID</label><input id="loginId" required placeholder="Enter your email or user ID"></div><div class="field"><label>Password</label><div class="password-wrap"><input id="loginPass" type="password" required placeholder="Enter password"><button type="button" class="eye" id="showPass">◉</button></div></div><div style="display:flex;justify-content:space-between;font-size:11px;margin:-3px 0 18px"><label><input type="checkbox"> Remember me</label><a href="#" style="color:var(--green)">Forgot password?</a></div><button class="primary full">Sign in to workspace →</button><div class="demo-box"><strong>Demo access</strong><div class="demo-row"><span>User: <code>user / user123</code></span><span>Support: <code>support / support123</code></span></div><div class="demo-row"><span>Admin: <code>admin / admin123</code></span></div></div></form></div></section>`}
const navItems=()=>[{id:'dashboard',label:'Dashboard',ico:'dash'},{id:'create',label:'Create Docket',ico:'plus'},{id:'dockets',label:'All Dockets',ico:'list'},...(session.role!=='user'?[{id:'reports',label:'Reports',ico:'report'}]:[]),...(session.role==='admin'?[{id:'fields',label:'Custom Fields',ico:'settings'},{id:'mail',label:'Mail Configuration',ico:'settings'}]:[]),{id:'profile',label:'My Profile',ico:'user'}];
function shell(content){return `<div class="mobile-overlay"></div><div class="app-shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">⌁</span>Dhruv-Setu</div><div class="nav-label">Workspace</div><nav class="nav">${navItems().map(n=>`<button data-page="${n.id}" class="${page===n.id?'active':''}">${icon(n.ico)}${n.label}</button>`).join('')}</nav><div class="user-chip"><div class="avatar">${session.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><strong>${session.name}</strong><span>${session.role[0].toUpperCase()+session.role.slice(1)}</span></div><button class="logout" title="Logout">↪</button></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn menu-toggle">☰</button><div class="page-title">${navItems().find(x=>x.id===page)?.label||'Dashboard'}</div></div><div class="top-actions"><button class="icon-btn">⌕</button><button class="icon-btn">♢</button><button class="primary" data-page="create">＋ Create Docket</button></div></header><div class="content">${content}</div></main></div>`}
function dashboard(){let total=state.dockets.length,n=state.dockets.filter(d=>d.status==='New').length,progress=state.dockets.filter(d=>d.status==='In Progress').length,closed=state.dockets.filter(d=>d.status==='Closed').length;let bars=[45,68,53,82,60,91,74];return `<div class="welcome"><div><h2>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${session.name.split(' ')[0]} 👋</h2><p>Here is what’s happening with your travel dockets today.</p></div><div class="date-pill">◷ &nbsp; 12 October 2026</div></div><section class="stats">${[['Total Dockets',total,'+12% this month'],['New Enquiries',n,'Needs attention'],['In Progress',progress,'Active bookings'],['Completed',closed,'+8% this month']].map((x,i)=>`<article class="card stat"><div class="stat-top"><span class="stat-label">${x[0]}</span><div class="stat-icon">${['▤','✦','◷','✓'][i]}</div></div><div class="stat-value">${x[1]}</div><span class="trend ${i==2?'neutral':''}">${x[2]}</span></article>`).join('')}</section><div class="grid-2"><section class="card"><div class="panel-head"><h3>Docket overview</h3><select class="outline"><option>Last 7 days</option><option>Last month</option></select></div><div class="panel-body"><div style="font-size:10px;color:var(--muted)"><b style="color:var(--green)">●</b> Created &nbsp; <b style="color:#b4e8dd">●</b> Completed</div><div class="chart">${bars.map((b,i)=>`<div class="bar-group"><div class="bar" style="height:${Math.max(18,b-22)}%"></div><div class="bar alt" style="height:${b}%"></div><span class="bar-label">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></div></section><section class="card"><div class="panel-head"><h3>Recent activity</h3><button class="outline" data-page="dockets">View all</button></div><div class="panel-body">${state.dockets.slice(0,4).map(d=>`<div class="activity"><i class="dot"></i><div><strong>${d.name} · ${d.location}</strong><span>${d.id} was ${d.status==='New'?'created':'updated'} · ${d.created}</span></div></div>`).join('')}</div></section></div>`}
function createDocket(){let next=`DS-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(Math.floor(1000+Math.random()*9000))}`;return `<div class="form-shell"><form class="section-card form-card" id="docketForm"><h3>Customer & booking details</h3><div class="form-grid"><div class="field"><label>Mobile Number *</label><input name="number" required maxlength="15" placeholder="e.g. 98765 43210"></div><div class="field"><label>Customer Name *</label><input name="name" required placeholder="Full name"></div><div class="field"><label>Email Address *</label><input name="email" type="email" required placeholder="customer@email.com"></div><div class="field"><label>Location / Destination *</label><input name="location" required placeholder="e.g. Goa, Manali"></div><div class="field span-2"><label>Address</label><textarea name="address" placeholder="Customer's complete address"></textarea></div><div class="field span-2"><label>Query / Requirement *</label><textarea name="query" required placeholder="What is the customer looking for?"></textarea></div><div class="field span-2"><label>Remarks</label><textarea name="remark" placeholder="Any additional notes..."></textarea></div>${state.fields.filter(f=>f.enabled).map(f=>`<div class="field ${f.type==='Checkbox'?'':'span-2'}"><label>${f.label}</label>${f.type==='Dropdown'?`<select name="field_${f.id}"><option value="">Select an option</option>${f.options.split(',').map(o=>`<option>${o.trim()}</option>`).join('')}</select>`:`<label style="padding:10px 0"><input type="checkbox" name="field_${f.id}" style="width:auto"> Yes, required</label>`}</div>`).join('')}</div><input type="hidden" name="id" value="${next}"><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:8px"><button type="reset" class="outline">Clear form</button><button class="primary">Create Docket & Send Email →</button></div></form><aside class="section-card side-info"><h3>Docket reference</h3><div class="docket-preview">${next}</div><div class="info-box" style="margin-top:17px"><b>What happens next?</b><br>✓ Docket saves to your workspace<br>✓ Customer receives a confirmation email<br>✓ Admin & support can track the request</div><div class="info-box"><b>Email variables used</b><br>{{customer_name}}<br>{{docket_number}}<br>{{location}}</div></aside></div>`}
function docketTable(){return `<section class="section-card"><div class="toolbar"><input class="search" id="search" placeholder="⌕  Search name, number or docket ID"><select id="statusFilter"><option value="">All status</option><option>New</option><option>In Progress</option><option>Closed</option></select><input type="date" id="dateFilter"><button class="outline" id="clearFilter">Clear</button></div><div class="table-wrap"><table><thead><tr><th>Docket ID</th><th>Customer</th><th>Destination</th><th>Query</th><th>Created</th><th>Status</th></tr></thead><tbody id="docketRows">${rows(state.dockets)}</tbody></table></div></section>`}
function rows(ds){return ds.length?ds.map(d=>`<tr><td><strong>${d.id}</strong></td><td>${d.name}<br><small style="color:var(--muted)">${d.number}</small></td><td>${d.location}</td><td>${d.query}</td><td>${d.created}</td><td><span class="badge ${d.status==='In Progress'?'pending':d.status==='Closed'?'closed':''}">${d.status}</span></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No matching dockets found.</td></tr>`}
function reports(){return `<div class="welcome"><div><h2>Reports & exports</h2><p>Filter and download docket data for your team.</p></div>${session.role==='support'&&!state.reportsAllowed?'<span class="badge pending">Access disabled by admin</span>':''}</div><section class="section-card"><div class="toolbar"><select id="reportRange"><option>Daily report</option><option>Weekly report</option><option>Monthly report</option><option>Custom range</option></select><input type="date"><input type="date"><select><option>All users</option><option>Amit Kumar</option><option>Priya Support</option></select><button class="primary" id="downloadReport" ${session.role==='support'&&!state.reportsAllowed?'disabled':''}>↓ Download CSV</button></div><div class="panel-body"><div class="stats" style="margin:0">${[['Total',state.dockets.length],['New',state.dockets.filter(x=>x.status==='New').length],['In progress',state.dockets.filter(x=>x.status==='In Progress').length],['Closed',state.dockets.filter(x=>x.status==='Closed').length]].map(x=>`<div class="stat" style="background:#f7faf8;border-radius:12px"><span class="stat-label">${x[0]}</span><div class="stat-value">${x[1]}</div></div>`).join('')}</div></div></section>`}
function fields(){return `<div class="settings-grid"><section class="section-card settings-card"><h3>Custom docket fields</h3><p>Create flexible fields that appear in the user and support docket form.</p><div id="fieldList">${state.fields.map(f=>`<div class="dynamic-item"><div><strong>${f.label}</strong><span>${f.type}${f.options?' · '+f.options:''}</span></div><button class="switch ${f.enabled?'on':''}" data-toggle-field="${f.id}"></button><button class="danger-btn" data-delete-field="${f.id}">×</button></div>`).join('')}</div><button class="primary" id="addField">＋ Add new field</button></section><section class="section-card settings-card"><h3>Role permissions</h3><p>Control what support users can access.</p><div class="toggle-row"><div><strong>Support report download</strong><span>Allow support agents to export CSV reports</span></div><button class="switch ${state.reportsAllowed?'on':''}" id="reportPermission"></button></div><div class="toggle-row"><div><strong>Support docket creation</strong><span>Allow support to create customer dockets</span></div><button class="switch on"></button></div><div class="toggle-row"><div><strong>User email confirmation</strong><span>Send confirmation after docket creation</span></div><button class="switch on"></button></div></section></div>`}
function mail(){return `<form class="settings-grid" id="mailForm"><section class="section-card settings-card"><h3>SMTP configuration</h3><p>Connect the sender account used for customer notifications.</p><div class="field"><label>SMTP Host</label><input name="host" value="${state.mail.host}"></div><div class="form-grid"><div class="field"><label>Port</label><input name="port" value="${state.mail.port}"></div><div class="field"><label>Encryption</label><select><option>TLS</option><option>SSL</option></select></div></div><div class="field"><label>Sender Email</label><input name="sender" value="${state.mail.sender}"></div><div class="field"><label>App Password</label><input type="password" placeholder="••••••••••••"></div><button type="button" class="outline" id="testMail">Send test email</button></section><section class="section-card settings-card"><h3>Docket confirmation template</h3><p>Personalise automated emails with smart variables.</p><div class="field"><label>Subject</label><input name="subject" value="${state.mail.subject}"></div><div class="field"><label>Email Body</label><textarea name="body" style="min-height:190px">${state.mail.body}</textarea></div><div class="info-box"><b>Available variables:</b><br>{{customer_name}} &nbsp; {{docket_number}}<br>{{location}} &nbsp; {{mobile_number}}</div><button class="primary">Save mail settings</button></section></form>`}
function profile(){return `<section class="section-card profile-card"><div class="profile-head"><div class="avatar">${session.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><h3>${session.name}</h3><p>${session.role[0].toUpperCase()+session.role.slice(1)} account · Active</p></div></div><form id="profileForm"><div class="form-grid"><div class="field"><label>Full Name</label><input name="name" value="${session.name}"></div><div class="field"><label>Email Address</label><input value="${session.email}"></div><div class="field"><label>User Role</label><input value="${session.role}" disabled></div><div class="field"><label>Phone Number</label><input placeholder="Add phone number"></div></div><button class="primary">Save changes</button></form></section>`}
function render(){if(!session){$('#app').innerHTML=loginView();bindLogin();return}let views={dashboard:dashboard(),create:createDocket(),dockets:docketTable(),reports:reports(),fields:fields(),mail:mail(),profile:profile()};$('#app').innerHTML=shell(views[page]||views.dashboard);bindApp()}
function bindLogin(){$('#showPass').onclick=()=>{let i=$('#loginPass');i.type=i.type==='password'?'text':'password'};$('#loginForm').onsubmit=e=>{e.preventDefault();let id=$('#loginId').value.trim().toLowerCase(),role=Object.keys(users).find(r=>id===r||id===users[r].email);if(!role||users[role].pass!==$('#loginPass').value)return toast('Incorrect login ID or password');session={role,...users[role]};delete session.pass;sessionStorage.setItem('dsSession',JSON.stringify(session));render()}}
function bindApp(){$$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('.logout').onclick=()=>{session=null;sessionStorage.removeItem('dsSession');page='dashboard';render()};$('.menu-toggle').onclick=()=>{$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('show')};$('.mobile-overlay').onclick=()=>{$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('show')};if($('#docketForm'))$('#docketForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),d=Object.fromEntries(f);d.status='New';d.created=new Date().toISOString().slice(0,10);d.owner=session.role;state.dockets.unshift(d);save();toast(`Docket ${d.id} created · Email queued`);page='dockets';setTimeout(render,650)};if($('#search')){let filter=()=>{let q=$('#search').value.toLowerCase(),s=$('#statusFilter').value,date=$('#dateFilter').value;$('#docketRows').innerHTML=rows(state.dockets.filter(d=>(!q||[d.id,d.name,d.number,d.location].join(' ').toLowerCase().includes(q))&&(!s||d.status===s)&&(!date||d.created===date)))};$('#search').oninput=filter;$('#statusFilter').onchange=filter;$('#dateFilter').onchange=filter;$('#clearFilter').onclick=()=>{$('#search').value='';$('#statusFilter').value='';$('#dateFilter').value='';filter()}}if($('#downloadReport'))$('#downloadReport').onclick=()=>{let csv='Docket ID,Customer,Mobile,Email,Destination,Query,Status,Created\n'+state.dockets.map(d=>[d.id,d.name,d.number,d.email,d.location,d.query,d.status,d.created].map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='dhruv-setu-report.csv';a.click();toast('Report downloaded successfully')};if($('#addField'))$('#addField').onclick=()=>showFieldModal();$$('[data-toggle-field]').forEach(b=>b.onclick=()=>{let f=state.fields.find(x=>x.id==b.dataset.toggleField);f.enabled=!f.enabled;save();render()});$$('[data-delete-field]').forEach(b=>b.onclick=()=>{state.fields=state.fields.filter(x=>x.id!=b.dataset.deleteField);save();render()});if($('#reportPermission'))$('#reportPermission').onclick=()=>{state.reportsAllowed=!state.reportsAllowed;save();render();toast('Support permission updated')};if($('#mailForm'))$('#mailForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.mail={...state.mail,...Object.fromEntries(f)};save();toast('Mail configuration saved')};if($('#testMail'))$('#testMail').onclick=()=>toast('Test email queued successfully');if($('#profileForm'))$('#profileForm').onsubmit=e=>{e.preventDefault();session.name=new FormData(e.target).get('name');sessionStorage.setItem('dsSession',JSON.stringify(session));toast('Profile updated');render()}}
function showFieldModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap"><form class="modal" id="fieldForm"><div class="modal-head"><h3>Add custom field</h3><button type="button" class="close">×</button></div><div class="field"><label>Field Label</label><input name="label" required placeholder="e.g. Preferred city"></div><div class="field"><label>Field Type</label><select name="type" id="fieldType"><option>Dropdown</option><option>Checkbox</option></select></div><div class="field" id="optionsField"><label>Options (comma separated)</label><input name="options" placeholder="Goa, Manali, Jaipur"></div><button class="primary full">Add field</button></form></div>`);$('.close').onclick=()=>$('.modal-wrap').remove();$('#fieldType').onchange=e=>$('#optionsField').classList.toggle('hidden',e.target.value==='Checkbox');$('#fieldForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));state.fields.push({id:Date.now(),...f,enabled:true});save();$('.modal-wrap').remove();toast('Custom field added');render()}}
render();
